// A foe's level is the card's own challenge level (F5.9b): the DC the stub would roll against, computed as the main engine's
// ladderOdds does: the rung (dc_tiers) or a character's stat, ± 4 per rung (rungStep), pulled toward the expected skill
// E(turn) by the drift (story none, milestone and crisis low, otherwise high, or the card's own word). A class's mean skill
// is its level, so a foe at level DC is the opponent the rung describes. The odds word moves the level by the measured
// fight odds instead of the stub's: in F5.9 the higher side wins 69% at +5 levels and 91% at +10, so likely (70%) is −5
// levels and sure (90%) −10. The luck word (steady, wild) changes nothing: a fight has its own variance.
const DRIFT={none:0,low:.15,mid:.3,high:.5};
const NATURE_LEVELS={certain:-15,sure:-10,likely:-5,even:0,unlikely:5,slim:8,long_shot:12,freak:20};
const defaultDrift=cardClass=>cardClass==='story'?'none':['milestone','crisis'].includes(cardClass)?'low':'high';
// {base: the rung's DC or the character's stat, rungs: ±n, drift: word, expected: E(turn)} → the DC.
function challengeDC({base,rungs=0,drift='high',expected,rungStep=4}){const b=base+rungs*rungStep;return b+(DRIFT[drift]??0)*(expected-b);}
function foeLevel({dc,nature='even'}){return Math.max(1,Math.min(100,Math.round(dc+(NATURE_LEVELS[nature]??0))));}
// A character named by `vs npc.stat ±n` keeps their shape: their current skills (canon × the main game's npc_growth),
// scaled to a mean skill of the foe's level (scaleToMean, as generateLoadout does), so the card's challenge level is their
// strength, as it is a class's. `stat` stays in the signature for the card's record; F5.9b set that stat to the level,
// which left a character about 15 levels weaker than the card's DC.
const namedFoeSkills=(skills,stat,level)=>scaleToMean(skills,level);

// A played card's fight setting: {context, observers, witnesses} for its i-th challenge and the foe chosen.
function fightSetting(key,i=0,foe){
 const e=EVENTS[key];if(!e?.play)throw Error('No played fight for '+key);
 const at=v=>Array.isArray(v)?v[i]:v,f=FOES[foe??[e.play].flat()[0]];
 return {context:at(e.context)??f?.context,observers:at(e.observers),witnesses:at(e.witnesses)};
}

// Every loadout a foe names must exist (checked by tools/event-coverage.mjs).
const foeLoadouts=()=>Object.values(FOES).flatMap(f=>f.pool?POOLS[f.pool]:[f.loadout]).filter(l=>!l.startsWith('('));
const knownLoadout=l=>!!(LOADOUTS[l]??NAMED_LOADOUTS[l]??SPECIAL_LOADOUTS[l]);

// ---- combat/setup/setup.mjs
// Fight setup: config defaults and validation, kits from the roster, entry resources and max HP. Plain data in, plain state out;
// the rules that play the fight live in the Rust core (web/core.mjs in the browser, rust/ natively).
const maps=n=>Object.fromEntries(RESOURCES.map(k=>[k,n]));
// The tuning's skill factor: the average over keys of 1 + perPoint × (skill − pivot).
const skillFactor=(skills,keys,perPoint,pivot=COMBAT_TUNING.skill.pivot)=>keys.reduce((n,k)=>n+1+perPoint*(skills[k]-pivot),0)/keys.length;
// Combat max HP's factor: hp.perPoint around hp.pivot (default the skill pivot), never below hp.min (default none).
const hpFactor=skills=>{const h=COMBAT_TUNING.hp;return Math.max(h.min??-Infinity,skillFactor(skills,h.skills,h.perPoint,h.pivot??COMBAT_TUNING.skill.pivot));};
// Condition on entering ({health, mana} as fractions, 1 = fit and full) → the share of max HP the fight starts with, the
// share of Mana capacity ready, and the share that starts as flux. HP: healthFloor + (1 − healthFloor) × health down to the
// knee (Health healthKnee), then straight down to hpAtZero at Health 0. Mana (manaAsFlux): ready = the Mana you had, flux =
// the rest of capacity; without manaAsFlux, the F5.4 floor (manaFloor) and no flux.
function combatStart(condition={}){
 const c=COMBAT_TUNING.condition,clamp=x=>Math.min(1,Math.max(0,x??1)),h=clamp(condition.health),m=clamp(condition.mana);
 const line=x=>c.healthFloor+(1-c.healthFloor)*x,knee=(c.healthKnee??0)/c.healthFull;
 const hp=h>=knee?line(h):c.hpAtZero+(line(knee)-c.hpAtZero)*h/knee;
 return c.manaAsFlux?{hp,mana:m,flux:1-m}:{hp,mana:c.manaFloor+(1-c.manaFloor)*m,flux:0};
}
// {skills:{arcana,…}, spells:{id:rank}, level?} → a kit like generateLoadout's (skills 1–100, ranks within the spell's levels).
function customKit({skills,spells,level}){
 for(const k of LOADOUT_SKILLS)if(!Number.isFinite(skills?.[k])||skills[k]<1||skills[k]>100)throw Error('Kit skill '+k+' must be 1–100');
 for(const [id,r]of Object.entries(spells??{}))if(!SPELLS[id]||SPELLS[id].castable===false||!Number.isInteger(r)||r<1||r>SPELLS[id].cost.length)throw Error('Kit spell '+id);
 const lv=level??Math.round(Math.max(...LOADOUT_SKILLS.map(k=>skills[k])));
 return {loadout:'custom',level:lv,progression:'learned',skills:{...skills},spells:{...spells},capacity:manaCapacity(skills)};
}
// A side's AI settings: {preset} expands to AI_PRESETS[preset] (the side's own keys win); persona true takes the loadout's
// persona (PERSONAS), an object is the persona itself; the persona joins `tilt`. Hard's persona:false drops it.
function expandAI(ai,loadout){
 if(!ai)return ai;
 const {preset,persona,...own}=ai,base=preset?AI_PRESETS[preset]:{};
 if(preset&&!base)throw Error('Unknown AI preset '+preset);
 const {persona:presetPersona,...settings}=base??{},use=persona??presetPersona;
 const tilt=use===false||use===undefined?own.tilt:{...(use===true?personaOf(loadout):use),...own.tilt};
 return {...settings,...own,...(tilt&&Object.keys(tilt).length?{tilt}:{}),...(preset?{preset}:{})};
}
function createState(options={}){
 const config={mode:'combat',playerLoadout:'Duellist',opponentLoadout:options.playerLoadout??'Duellist',playerYear:1,opponentYear:options.playerYear??1,playerIlseTaken:false,opponentIlseTaken:options.playerIlseTaken??false,playerLevel:50,opponentLevel:options.playerLevel??50,
  spellAccess:'kit',resourceBudget:'standard',manaCostScale:1,combatScale:1,damageMultiplier:1,encounterSeed:options.opponentLevel??options.playerLevel??50,firstLeader:1,healthModel:'direct',context:'practice_duel',observers:false,...options};
 // witnesses (optional): someone who would report a forbidden cast; the core defaults it to observers (an audience always is one).
 if(!Number.isInteger(config.encounterSeed)||config.encounterSeed<0||config.encounterSeed>0xffffffff)throw Error('Encounter seed must be an integer from 0 to 4294967295');
 const enemy=config.opponentLoadout==='random'?Object.keys(LOADOUTS)[Math.floor(levelRng(config.encounterSeed)()*Object.keys(LOADOUTS).length)]:config.opponentLoadout;
 config.resolvedOpponentLoadout=enemy;
 if(Array.isArray(config.ai))config.ai=config.ai.map((a,side)=>expandAI(a,side?enemy:config.playerLoadout));
 if(config.mode!=='combat'||!['direct','offset'].includes(config.healthModel)||!['standard','depleted'].includes(config.resourceBudget)||![0,1].includes(config.firstLeader)||!CONTEXTS[config.context]||typeof config.observers!=='boolean'||config.witnesses!==undefined&&(typeof config.witnesses!=='boolean'||config.observers&&!config.witnesses))throw Error('Invalid combat setup');
 if(!Number.isFinite(config.manaCostScale)||config.manaCostScale<=0||!Number.isFinite(config.combatScale)||config.combatScale<=0||!Number.isFinite(config.damageMultiplier)||config.damageMultiplier<=0)throw Error('Positive scales required');
 const rebates={...CONTEXTS[config.context],...options.rebates,crowns:0,alignment:0};
 for(const n of Object.values(rebates))if(!Number.isFinite(n)||n<0||n>1)throw Error('Rebates must be in [0,1]');
 const actors=[0,1].map(side=>{
  // A side's own kit (the player's learned spells, setup/campaign.mjs) instead of a generated preset.
  const own=side?options.opponentKit:options.playerKit;
  const kit=own?customKit(own):generateLoadout(side?enemy:config.playerLoadout,side?config.opponentLevel:config.playerLevel,config.spellAccess,{year:side?config.opponentYear:config.playerYear,ilseTaken:side?config.opponentIlseTaken:config.playerIlseTaken,skills:side?options.opponentSkills:options.playerSkills}),standard=config.resourceBudget==='standard';
  let overrides=side?options.opponentResources:options.playerResources;
  if(side&&!overrides&&config.playerLoadout===enemy&&config.playerLevel===config.opponentLevel&&options.playerResources){const {crowns,...mirrored}=options.playerResources;overrides=mirrored;}
  const entry={health:standard?70:35,mood:standard?60:30,renown:standard?30:5,mana:standard?kit.capacity:Math.min(30,kit.capacity),crowns:standard?30:6,alignment:0,...overrides};
  for(const [k,n]of Object.entries(entry))if(!RESOURCES.includes(k)||!Number.isFinite(n)||n<(k==='alignment'?-100:0)||n>(k==='mana'?kit.capacity:k==='crowns'?99999:100))throw Error('Invalid entry '+k);
  const maxHP=(config.healthModel==='offset'?entry.health+40+Math.floor((kit.skills.arcana+kit.skills.vigor)/4):Math.round(entry.health*hpFactor(kit.skills)))*(config.hpScale??1);
  if(maxHP<=0)throw Error('Positive entry HP required');
  // A worn or drained side starts below full (playerCondition / opponentCondition).
  const condition=side?options.opponentCondition:options.playerCondition,start=combatStart(condition);
  const story=side?options.opponentStart:options.playerStart;   // the story's own handicap ({hp, mana} shares, no floors)
  let hp=condition?Math.max(1,Math.round(maxHP*start.hp)):maxHP,flux=0;
  if(condition){entry.mana=Math.min(entry.mana,Math.round(kit.capacity*start.mana));if(start.flux>0)flux=kit.capacity-entry.mana;}   // 10 of 43 Mana → 10 ready, 33 flux
  if(story?.hp!==undefined)hp=Math.max(1,Math.round(hp*story.hp));
  if(story?.mana!==undefined)entry.mana=Math.round(entry.mana*story.mana);
  flux=Math.max(0,Math.min(flux,kit.capacity-entry.mana));
  return {kit,entry,resources:{...entry},spent:maps(0),restored:maps(0),hp,maxHP,startHP:hp,flux,effects:{},channel:null,constructs:[],omens:[],lastAction:null,rimeReady:false,rimeUsed:false,freezeUntil:0,pendingRenown:0,glamourDone:false,guardRound:0};
 });
 config.resolvedPlayerLevel=actors[0].kit.level;config.resolvedOpponentLevel=actors[1].kit.level;
 return {config,rebates,actors,quiet:0,round:1,normalLeader:config.firstLeader,leader:config.firstLeader,earlyCommit:[0,0],pending:[null,null],lastPair:null,lastEvents:[],reports:[],bursts:[],result:null,settlement:null};
}

// ---- combat/setup/flavor.mjs
// What each action looks like, for the fight log and the telegraph: one plain sentence of what the fighter visibly does
// and what it does in this fight. No numbers or rules (the action's description gives those), no inner states, no gore.
// When a spell is no use in a fight, the line says so ("…, but it does little here").
//   {name}  the fighter acting (or holding the effect, for `end`); {foe}  the other fighter. The player is "you" (F5.9b), so:
//   {name’s} / {foe’s}  possessive ("your", "Lyra’s"); {v:third|second} the form agreeing with {name} ("lunges|lunge",
//   "is|are"), {fv:third|second} the same for {foe}; {pos} / {fpos} / {fobj} pronouns (fighterNames: opponentPronouns).
//   cast:    the action as it happens (a list rotates by exchange)
//   hold / release:  a channel's held and released exchanges (cast is its first exchange)
//   end:     a lasting effect or construct ending (Mend: the wounds closing; `broken` when a hit spoils it)
//   ko:      this action finishing the foe
//   tired:   (Guard) a Guard raised again too soon, against a Strike
// Names come from the fight (fighterNames below): "you" for the player, the opponent as the card names them.
const FLAVOR={
 // Basics
 strike:{cast:['{name} {v:lunges|lunge} in and {v:swings|swing} at {foe}.','{name} {v:closes|close} the distance and {v:strikes|strike} at {foe}.','{name} {v:throws|throw} a quick blow at {foe}.'],ko:'{foe} {fv:goes|go} down under {name’s} blows.'},
 guard:{cast:['{name} {v:raises|raise} a guard against {foe’s} blows.','{name} {v:steps|step} back, arms up, ready for {foe}.'],tired:'{name’s} guard sags, and {foe’s} blows start to get through.'},
 reclaim:{cast:['{name} {v:draws|draw} the spent magic in the air back in.','{name} {v:gathers|gather} up the loose sparks of magic left in the air.']},
 frozen:{cast:['{name} {v:is|are} frozen solid in rime and can’t move.'],end:'The rime around {name} cracks, and {name} {v:moves|move} again.'},

 // Course spells and Ward
 flame:{cast:['A burst of flame leaps from {name’s} hand at {foe}.','{name} {v:hurls|hurl} a ball of fire at {foe}.'],ko:'{foe} {fv:falls|fall} before {name’s} fire.'},
 foresight:{cast:['{name’s} eyes glaze over, reading {foe’s} next moves before they happen.'],end:'{name} can no longer read {foe’s} moves ahead.'},
 mend:{cast:['{name} {v:lays|lay} a glowing hand on {pos} wounds and {v:starts|start} to knit them shut.'],end:'{name’s} wounds close up.',broken:'{foe’s} attack breaks {name’s} mending before it can take hold.'},
 glamour:{cast:['{name} {v:strikes|strike} a dazzling pose for the onlookers, but it does nothing to {foe}.']},
 haste:{cast:['{name} {v:speeds|speed} up, moving twice as fast as {foe}.'],end:'{name} {v:slows|slow} back to a normal pace.'},
 shadowstep:{cast:['{name} {v:steps|step} into the shadows, out of {foe’s} reach.'],end:'{name} {v:steps|step} back out of the shadows.'},
 ward:{cast:['A translucent ward appears before {name}, blocking off {foe’s} spells.']},

 // Hidden courses
 animate:{cast:['A chair, a coat stand and a bucket lurch to life and lumber at {foe} on {name’s} command.'],end:'{name’s} animated furniture clatters apart.',ko:'{foe} {fv:goes|go} down under {name’s} animated furniture.'},
 starlight:{cast:['Starlight gathers in {name’s} open palm.'],hold:'The starlight in {name’s} palm grows brighter.',release:'A beam of starlight shoots from {name’s} palm at {foe}.',ko:'{foe} {fv:falls|fall} in a flood of {name’s} starlight.'},
 seal:{cast:['{name} {v:twists|twist} a hand, snuffing out the loose magic around {foe}.']},

 // Peer capstones
 wildfire:{cast:['A cluster of flames sparks to life before {name} and lashes out at {foe}.'],hold:'The cluster of flames enlarges before {name}, radiating fiery sparks.',release:'The wildfire breaks loose from {name} and sweeps over {foe}.',ko:'{foe} {fv:falls|fall} before {name’s} wildfire.'},
 heartwood:{cast:['A sapling bursts from the floor beside {name}, ready to shelter and mend.'],end:'{name’s} sapling withers back into the floor.'},
 omen:{cast:['{name} {v:speaks|speak} an omen over {foe}: it will strike in two exchanges.'],end:'The omen {name} spoke comes true and strikes {foe}.'},
 sleight:{cast:['{name} {v:slips|slip} a hand into {foe’s} purse in passing.']},
 contraption:{cast:['{name} {v:snaps|snap} together a whirring contraption and {v:aims|aim} it at {foe}.'],end:'{name’s} contraption bursts in a shower of sparks and cogs.'},
 hoarfrost:{cast:['A lance of frost flies from {name} at {foe}.'],ko:'{foe} {fv:falls|fall}, frozen stiff by {name’s} frost.'},
 candour:{cast:['{name} {v:asks|ask} {foe} a disarming question, but it does little here.']},

 // Club and job spells
 brace:{cast:['{name} {v:plants|plant} both feet, braced to take {foe’s} hits.'],end:'{name} {v:eases|ease} out of the braced stance.'},
 quickquill:{cast:['A quill flies around {name}, but it does little in this situation.']},
 bramble:{cast:['Thorny vines burst from the floor around {foe} at {name’s} call.'],end:'{name’s} brambles wither away.'},
 index:{cast:['{name} {v:leafs|leaf} through a conjured index, but it does little here.']},
 rapport:{cast:['{name} {v:flaunts|flaunt} a handful of crowns, and the crowd cheers.']},
 purify:{cast:['{name} {v:draws|draw} some of {pos} own strength out and {v:distils|distil} it into magic.']},
 // Creatures (SPECIAL_LOADOUTS)
 gore:{cast:['{name} {v:lowers|lower} its antlers and {v:charges|charge} at {foe}.','{name} {v:paws|paw} the ground, then {v:drives|drive} its antlers at {foe}.'],ko:'{foe} {fv:is|are} flung down by {name’s} charge.'},
 tailwind:{cast:['A wind rises at {name’s} back, driving each blow harder.'],end:'The wind at {name’s} back dies down.'},

 // Hidden pool
 rime:{cast:['{name} {v:sews|sew} a sliver of rime into {pos} collar, against a fall.']},
 reflect:{cast:['A mirror-bright sheen settles over {name}, ready to throw {foe’s} spells back.'],end:'The mirror sheen around {name} fades.'},
 moonwell:{cast:['A pool of moonlight opens at {name’s} feet.'],hold:'The moonwell at {name’s} feet fills higher.',release:'{name} {v:drinks|drink} the moonwell down and {v:fills|fill} with magic.'},
 lodestar:{cast:['A small star kindles above {name}.'],hold:'The star above {name} grows heavier, pulling in loose force.',release:'The star settles around {name} as a shield.'},
 toll:{cast:['A single bell note sounds from nowhere.']},

 // Forbidden pool
 torment:{cast:['{name} {v:lays|lay} a curse on {foe}: every move will hurt.'],end:'{name’s} curse on {foe} wears off.'},
 extraction:{cast:['{name} {v:pulls|pull} the ready magic straight out of {foe}.']},
 siphon:{cast:['A dark thread links {name} to {foe} and starts to drink.'],hold:'The dark thread drinks more from {foe}.',release:'{name} {v:snaps|snap} the thread and {v:takes|take} in everything it drank.',ko:'{foe} {fv:sags|sag}, drained by {name’s} dark thread.'},
 compel:{cast:['{name} {v:speaks|speak} a word of command, and {foe} {fv:repeats|repeat} {fpos} last move.'],end:'{name} {v:shakes|shake} off the compulsion.',forced:'{name} {v:is|are} compelled to repeat {pos} last move: {action}.',shut:'{foe’s} defences shut out {name’s} command.'},
 eclipse:{cast:['A dark disc slides over {name}, turning the next blows into magic.'],end:'The eclipse over {name} passes.'},
 heartprice:{cast:['{name} {v:strikes|strike} a bargain: from now on, spells cost life instead of magic.']}
};
// How a fight ends, when the finishing action has no ko line of its own (or it isn't a knockout).
// A foe whose defeat isn't a fall (F5.9): its own line however the fight ends, {name} the winner, {foe} the foe.
const DEFEAT={'Shadow stag':'{foe} {fv:lowers|lower} its head and {fv:steps|step} aside for {name}.'};
const ENDINGS={knockout:'{foe} can fight no more, and {name} {v:wins|win}.',decision:'Neither falls; {name} {v:wins|win} on points.',stalemate:'Neither {name} nor {foe} can finish it: a draw.',conceded:'{foe} {fv:yields|yield} to {name}.'};
// Effects that end with a line, by effect key → the spell whose `end` it uses. {name} is the effect's holder, except for
// Torment, whose effect sits on the cursed side but is told from the caster's.
const LASTING={brace:'brace',haste:'haste',shadowstep:'shadowstep',tailwind:'tailwind',reflect:'reflect',torment:'torment',eclipse:'eclipse',compelled:'compel'};
const HELD_BY_FOE=new Set(['torment']);

// The two fighters' names, [player, opponent]: the player is always "you" (F5.9b); the main game passes the card's opponent,
// and the bench names generic loadouts "the Duellist" and characters by name. Names starting "The" read lower-case mid-sentence.
const YOU='you';
// Pronouns for {pos} / {fpos} (possessive) and {fobj} (object). The main game passes a character's own (their worldbook
// `pronouns:`, e.g. 'she'); generic foes are 'they' and creatures 'it'. The player is 'you'.
const PRONOUNS={you:{pos:'your',obj:'you'},they:{pos:'their',obj:'them'},she:{pos:'her',obj:'her'},he:{pos:'his',obj:'him'},it:{pos:'its',obj:'it'}};
function fighterNames({opponentName,opponentLoadout,opponentPronouns}={}){
 const of=l=>!l?null:NAMED_LOADOUTS[l]?l.replace(/^The /,'the '):SPECIAL_LOADOUTS[l]?'the '+l.toLowerCase():'the '+l;
 const names=[YOU,opponentName??of(opponentLoadout)??'the opponent'];
 const p=String(opponentPronouns??(SPECIAL_LOADOUTS[opponentLoadout]?'it':'they')).split('/')[0].toLowerCase();
 names.pronouns=['you',PRONOUNS[p]?p:'they'];
 return names;
}
const possessive=n=>n===YOU?'your':n+'’s';
const pron=(n,p)=>PRONOUNS[n===YOU?'you':p]??PRONOUNS.they;
const fill=(line,name,foe,pn,pf)=>{if(!line)return null;
 const s=line.replaceAll('{name’s}',possessive(name)).replaceAll('{foe’s}',possessive(foe))
  .replaceAll('{pos}',pron(name,pn).pos).replaceAll('{fpos}',pron(foe,pf).pos).replaceAll('{fobj}',pron(foe,pf).obj)
  .replace(/\{(f?)v:([^|}]*)\|([^}]*)\}/g,(_,f,third,second)=>(f?foe:name)===YOU?second:third)
  .replaceAll('{name}',name).replaceAll('{foe}',foe);
 return s[0].toUpperCase()+s.slice(1);};
const pick=(x,round)=>Array.isArray(x)?x[(round-1)%x.length]:x;
const BUNDLE_PART={strike:'a blow',guard:'a guard',reclaim:'a breath to gather magic'};

// The line for one side's action: a channel's Hold/Release, a Haste bundle as its parts, else the cast line.
//   names: [player, opponent]; side: who acts.
function flavorLine(id,{channel=null,round=1,names=['the player','the opponent'],side=0}={}){
 const name=names[side],foe=names[1-side],pr=[names.pronouns?.[side],names.pronouns?.[1-side]];
 if(id==='hold'||id==='release')return fill(FLAVOR[channel]?.[id],name,foe,...pr);
 if(id?.startsWith('bundle:'))return fill('{name} {v:moves|move} at double speed: '+id.slice(7).split('+').map(p=>BUNDLE_PART[p]).join(', then ')+'.',name,foe,...pr);
 return fill(pick(FLAVOR[id]?.cast,round),name,foe,...pr);
}
// What an attack looks like when a defence changed it (F5.9b), by the attack and the defence that mattered most; any attack
// without its own line uses ATTACK_DEFENDED with its noun. {name} the attacker, {foe} the target.
const ATTACK_NOUN={strike:'blow',flame:'fireball',hoarfrost:'frost lance',gore:'charge',wildfire:'wildfire',starlight:'beam of starlight',siphon:'dark thread',bramble:'thorns',animate:'furniture',contraption:'contraption',omen:'omen',heartwood:'sapling'};
const ATTACK_LINES={
 strike:{evaded:'{name} {v:swings|swing} at {foe}, but {foe} {fv:is|are} in the shadows and the blow meets nothing.',guarded:'{foe} {fv:catches|catch} {name’s} blow on a raised guard.',tiredGuard:'{foe’s} tired guard gives, and part of {name’s} blow gets through.',warded:'{name’s} blow thuds into {foe’s} ward, losing half its force.',braced:'{foe} {fv:takes|take} {name’s} blow braced, barely moving.'},
 flame:{evaded:'{name’s} fireball passes through the shadows where {foe} stood.',warded:'{name’s} fireball splashes against {foe’s} ward and fizzles out.',guarded:'{foe} {fv:takes|take} {name’s} fireball on crossed arms, smothering half the burn.',braced:'{foe} {fv:plants|plant} {fpos} feet and {fv:weathers|weather} {name’s} fireball.',reflected:'{name’s} fireball bounces off {foe’s} mirror sheen and flies back at {name}.'},
 hoarfrost:{evaded:'{name’s} frost lance flies through the shadows where {foe} stood.',warded:'{name’s} frost lance shatters on {foe’s} ward.',guarded:'{foe} {fv:knocks|knock} {name’s} frost lance aside, taking half the chill.',reflected:'{name’s} frost lance glances off {foe’s} mirror sheen and turns back on {name}.'},
 gore:{evaded:'{name} {v:charges|charge} into the shadows and finds no one there.',guarded:'{foe} {fv:catches|catch} {name’s} antlers on a raised guard.',warded:'{name’s} antlers drive into {foe’s} ward, which takes half the charge.',braced:'{foe} {fv:meets|meet} {name’s} charge braced and {fv:holds|hold} firm.'},
 wildfire:{embers:'{foe’s} defences stop the heart of {name’s} wildfire, but its embers burn through.',evaded:'{name’s} wildfire sweeps through the shadows where {foe} stood.',warded:'{name’s} wildfire breaks against {foe’s} ward and burns out.',guarded:'{foe} {fv:shields|shield} {fpos} face from {name’s} wildfire, taking half of it.',reflected:'{name’s} wildfire rolls off {foe’s} mirror sheen and back over {name}.'},
 starlight:{evaded:'{name’s} beam of starlight lights up empty shadows.',warded:'{name’s} beam of starlight scatters on {foe’s} ward.',guarded:'{foe} {fv:turns|turn} {fpos} guard to {name’s} starlight, taking half of it.',reflected:'{name’s} starlight bounces off {foe’s} mirror sheen straight back at {name}.'}
};
const ATTACK_DEFENDED={evaded:'{foe} {fv:is|are} in the shadows: {name’s} {noun} passes straight through.',warded:'{foe’s} ward stops {name’s} {noun}.',guarded:'{foe} {fv:takes|take} {name’s} {noun} on a raised guard.',tiredGuard:'{foe’s} tired guard lets part of {name’s} {noun} through.',braced:'{foe} {fv:weathers|weather} {name’s} {noun} in a braced stance.',reflected:'{foe’s} mirror sheen throws {name’s} {noun} back at {name}.',absorbed:'{foe’s} shield soaks up part of {name’s} {noun}.',frozen:'{foe} {fv:is|are} frozen in rime, and {name’s} {noun} can’t touch {foe}.'};
// What a lasting effect does, for "for N exchanges" sentences. {n} the exchanges it lasts; {x} its value where it has one.
const EFFECT_WORDS={
 shadowstep:'{name} can’t be hit for {n}, until {name} {v:attacks|attack} or {v:gathers|gather} Mana.',
 haste:'{name} {v:acts|act} {x} times in each of the next {n}.',
 brace:'{name} {v:blocks|block} all damage this exchange, then half, a quarter and a quarter.',
 tailwind:'{name’s} blows hit harder for {n}.',
 reflect:'Spells cast at {name} bounce back for {n}.',
 torment:'Every move {foe} {fv:makes|make} costs {fobj} Health for {n}.',
 eclipse:'Blows that hit {name} turn into Mana for {n}.',
 compelled:'{foe} must repeat {fpos} last move next exchange.',
 heartprice:'{name’s} spells cost Health instead of Mana from now on.',
 lodestar:'A shield of {x} absorbs the next damage {name} {v:takes|take}.'
};
const EFFECT_ON_FOE=new Set(['torment','compelled']);   // placed on the foe, told from the caster's side
const ex=n=>n===1?'1 exchange':n+' exchanges';
const r0=x=>Math.round(x);
// The most telling defence on a hit: what the defender's line should say.
function defence(by){for(const d of ['shadowstep','reflect','frozen','ward','tiredGuard','guard','brace','construct','lodestar'])if(by.includes(d))return d==='construct'||d==='lodestar'?'absorbed':d==='shadowstep'?'evaded':d==='ward'?'warded':d==='guard'?'guarded':d==='brace'?'braced':d==='reflect'?'reflected':d;return null;}
// The log line for each side's action in a resolved exchange, with its consequences in plain words: the attack and what
// stopped or let it through ("Lyra takes 14 damage"), and what a non-attack did ("for 3 exchanges", "regains 9 Mana").
//   before/after: plain state snapshots; r: the resolved exchange ({pair, round, channels, eventData}); names: [player, opponent].
function resolvedLines(before,after,r,names=['the player','the opponent']){
 const ev=r.eventData??[],out=[null,null];
 for(const side of [0,1]){
  const id=r.pair[side],ch=r.channels?.[side],spell=id==='hold'||id==='release'?ch:id?.startsWith('bundle:')?null:id;
  const name=names[side],foe=names[1-side],F=line=>fill(line,name,foe,names.pronouns?.[side],names.pronouns?.[1-side]),parts=[];
  const mine=ev.filter(e=>e.type==='hit'&&e.source===side&&!e.reflected);
  // Attacks: one sentence per kind of attack this side landed or lost, then the damage.
  const byId={};for(const e of mine)(byId[e.id]??=[]).push(e);
  const head=flavorLine(id,{channel:ch,round:r.round,names,side});
  let usedHead=false;
  for(const [aid,hits]of Object.entries(byId)){
   const dealt=hits.reduce((n,e)=>n+e.amount,0),def=hits.map(e=>defence(e.by)).find(Boolean);
   // Wildfire's embers (F5.9c) get through Guard and Ward, so a defended Release can still burn.
   const special=def&&(def!=='evaded'&&def!=='reflected'&&dealt>0&&ATTACK_LINES[aid]?.embers&&hits.length>1?ATTACK_LINES[aid].embers:ATTACK_LINES[aid]?.[def]??(def==='tiredGuard'?ATTACK_LINES[aid]?.guarded:null));
   const line=def?special??ATTACK_DEFENDED[def].replaceAll('{noun}',ATTACK_NOUN[aid]??'attack'):null;
   const own=aid===spell||aid==='strike'&&id?.startsWith('bundle:');
   if(line)parts.push(F(line));else if(own&&!usedHead&&head){parts.push(head);usedHead=true;}else if(!own)parts.push(F(`{name’s} ${ATTACK_NOUN[aid]??'attack'} hits {foe}.`));
   const back=ev.filter(e=>e.type==='hit'&&e.reflected&&e.source===1-side&&e.id===aid).reduce((n,e)=>n+e.amount,0);
   if(def==='reflected')parts.push(F(back>0?`{name} {v:takes|take} ${r0(back)} damage from {pos} own ${ATTACK_NOUN[aid]??'attack'}.`:'It does no damage.'));
   else parts.push(dealt>0?F(`{foe} {fv:takes|take} ${r0(dealt)} damage${hits.length>1?` from ${hits.length} hits`:''}.`):F('It does no damage.'));
  }
  if(!usedHead&&head&&!Object.keys(byId).includes(spell)&&!(id?.startsWith('bundle:')&&byId.strike))parts.unshift(head);
  // Non-attacks: what changed for this side.
  const b=before.actors[side],a=after.actors[side],bo=before.actors[1-side],ao=after.actors[1-side];
  const reclaimed=ev.filter(e=>e.type==='reclaimed'&&e.side===side).reduce((n,e)=>n+e.amount,0);
  if(reclaimed>0)parts.push(F(`{name} {v:regains|regain} ${r0(reclaimed)} Mana.`));
  else if(id==='reclaim'||id?.includes('reclaim'))parts.push(F('There is no loose magic left to gather.'));
  if(spell==='mend'&&!after.result)parts.push(a.hp>b.hp?F(`{name} {v:heals|heal} ${r0(a.hp-b.hp)} HP.`):F('The mending breaks: no healing.'));
  for(const m of ev.filter(e=>e.type==='moved'&&e.side===side)){const n=r0(m.amount);
   if(m.id==='extraction')parts.push(m.blocked?F('{foe’s} defences keep {fpos} Mana in place: it takes nothing.'):n>0?F(`${n} of {foe’s} Mana becomes {pos} loose magic.`):F('There is no room for more magic: it takes nothing.'));
   if(m.id==='seal')parts.push(m.blocked?F('{foe’s} defences keep {fpos} loose magic safe.'):n>0?F(`{foe} {fv:loses|lose} ${n} loose magic.`):F('There was no loose magic to snuff out.'));
   if(m.id==='purify')parts.push(F(`{name} {v:pays|pay} Health for ${n} Mana.`));}
  if(spell==='foresight'&&after.earlyCommit?.[1-side]>0)parts.push(F(`{foe} must commit first for the next ${ex(after.earlyCommit[1-side])}.`));
  for(const [k,words]of Object.entries(EFFECT_WORDS)){
   const holder=EFFECT_ON_FOE.has(k)?1-side:side,e1=after.actors[holder].effects?.[k],e0=before.actors[holder].effects?.[k];
   if(!e1||(e0&&e0.until===e1.until&&e0.from===e1.from))continue;
   if(LASTING_SPELL[k]!==spell)continue;
   const n=e1.until==null?null:e1.until-Math.max(e1.from,r.round)+1,x=k==='haste'?(after.actors[side].kit?.spells?.haste===3?'three':'two'):k==='tailwind'?`+${r0(e1.value)}`:k==='lodestar'?r0(e1.value):'';
   parts.push(F(words.replace('{n}',n==null?'the rest of the fight':ex(n)).replace('{x}',x)));
  }
  if(spell==='compel'&&!after.result){const took=isCompelled({...after,round:r.round+1},1-side);
   parts.length=0;parts.push(took?F(FLAVOR.compel.cast[0]):F(FLAVOR.compel.shut));
   if(took)parts.push(F(`{foe} must repeat it again next exchange${r.actionNames?.[1-side]?`: ${r.actionNames[1-side]}`:''}.`));}
  if(isCompelled({...before,round:r.round},side)||r.committed?.[side]&&r.committed[side]!==id&&r.pair[1-side]==='compel')parts.unshift(F('Compelled, {name} {v:repeats|repeat} {pos} last move.'));
  out[side]=parts.length?parts.join(' '):null;
 }
 return out;
}
// A side compelled this exchange (Compel, F5.9b): its move is forced and shown in advance.
const isCompelled=(state,side)=>{const e=state.actors[side].effects?.compelled;return !!e&&e.from<=state.round&&(e.until==null||e.until>=state.round);};
const compelledLine=(action,{names=['the player','the opponent'],side=1}={})=>fill(FLAVOR.compel.forced.replace('{action}',action),names[side],names[1-side],names.pronouns?.[side],names.pronouns?.[1-side]);
const LASTING_SPELL={shadowstep:'shadowstep',haste:'haste',brace:'brace',tailwind:'tailwind',reflect:'reflect',torment:'torment',eclipse:'eclipse',compelled:'compel',heartprice:'heartprice',lodestar:'lodestar'};
// Lines for what one resolved exchange finished, from plain snapshots of the state before and after it (no rules involved):
// a Mend heals or is broken, a tired Guard gives, lasting effects, Foresight and constructs end, a foretold Omen arrives,
// the rime thaws, and the fight ends (the finishing action's ko line, else ENDINGS).
function finishLines(before,after,pair,round,names=['the player','the opponent']){
 const out=[],add=(line,side)=>{const l=fill(line,names[side],names[1-side],names.pronouns?.[side],names.pronouns?.[1-side]);if(l&&!out.includes(l))out.push(l);};
 const g=COMBAT_TUNING.guard;
 for(const side of [0,1]){
  const id=pair[side],b=before.actors[side],a=after.actors[side];
  if(g?.repeatLeak>0&&(id==='guard'||id?.startsWith('bundle:')&&id.includes('guard'))&&b.guardRound>0&&round-b.guardRound<=(g.lookback??1)&&pair[1-side]?.includes('strike'))add(FLAVOR.guard.tired,side);
  for(const k of Object.keys(b.effects))if(!a.effects[k]&&LASTING[k])add(FLAVOR[LASTING[k]].end,HELD_BY_FOE.has(k)?1-side:side);
  if(before.earlyCommit[side]>0&&!after.earlyCommit[side])add(FLAVOR.foresight.end,1-side);
  for(const c of b.constructs)if(!a.constructs.some(x=>x.id===c.id))add(FLAVOR[c.id]?.end,side);
  if(b.omens.some(o=>o.due===round))add(FLAVOR.omen.end,side);
  if(id==='frozen'&&a.freezeUntil<=round)add(FLAVOR.frozen.end,side);
 }
 const r=after.result;
 if(r&&!before.result){
  const w=r.winner;
  if(w===undefined||w===null)add(ENDINGS.stalemate,0);
  else{
   const id=pair[w],key=id==='hold'||id==='release'?before.actors[w].channel?.id:id?.startsWith('bundle:')&&id.includes('strike')?'strike':id;
   add(DEFEAT[after.actors[1-w].kit?.loadout]??(r.reason==='knockout'?FLAVOR[key]?.ko??ENDINGS.knockout:ENDINGS[r.reason]??ENDINGS.knockout),w);
  }
 }
 return out;
}

// ---- combat/setup/campaign.mjs
// The bridge between the main game and a fight: the player's skills, learned spells, Health and Mana in; resource changes out.
// Numbers live in COMBAT_TUNING (setup/roster.mjs): condition (how worn or drained you start) and settle (what a fight costs).
//   const state=createState(fightOptions({player,opponent,context}))   … play with web/core.mjs …   settle(state,player)
// player:   {skills:{arcana,lore,alchemy,charm,vigor,guile}, spells:{id:rank}, health, mana, mood, renown, gold, alignment}
// opponent: {loadout, level} for a preset or named character, or {skills, spells} for a custom one; optional condition {health, mana}
// context, observers, witnesses: the card's fight setting (fightSetting in setup/foes.mjs: the rebates, an audience whose
// Renown counts, someone who would report a forbidden cast).
// The main game's Mana uses the fight's scale (INTEGRATION.md §2): its pool is manaCapacity(skills), so player.mana ≤ capacity.
// Spells with no effect in this fight stay out of the kit: Glamour and Rapport act only before an audience; Index and
// Quickquill never do. Sleight steals Crowns, so it stays.
const inFight=(id,observers)=>!COMBAT_EXCLUDED.has(id)||id==='sleight'||observers&&(id==='glamour'||id==='rapport');

function fightOptions({player,opponent,context='practice_duel',observers=false,witnesses=observers,firstLeader=1,encounterSeed}){
 const c=COMBAT_TUNING.condition,capacity=manaCapacity(player.skills);
 // Fit means Health at or above healthFull and Mana at or above the combat capacity. Below that: HP drops a little down to
 // Health 30 and steeply after; you keep exactly the Mana you had, and the rest of capacity starts as flux (combatStart).
 const playerCondition={health:Math.min(1,player.health/c.healthFull),mana:Math.min(1,player.mana/capacity)};
 const foe=opponent.loadout?{opponentLoadout:opponent.loadout,opponentLevel:opponent.level}:{opponentKit:{skills:opponent.skills,spells:opponent.spells,level:opponent.level}};
 const spells=Object.fromEntries(Object.entries(player.spells).filter(([id])=>inFight(id,observers)));
 return {playerKit:{skills:player.skills,spells,level:player.level},playerCondition,...foe,...(opponent.condition?{opponentCondition:opponent.condition}:{}),
  playerResources:{mood:clamp(player.mood??60,0,100),renown:clamp(player.renown??0,0,100),crowns:clamp(player.gold??0,0,99999),alignment:clamp(player.alignment??0,-100,100)},
  context,observers,witnesses,firstLeader,...(encounterSeed!==undefined?{encounterSeed}:{})};
}

// The settled fight → changes to the player's resources. Health: the share of combat HP lost × the stake, less the context's
// rebate; never below 1 (a lost duel hurts, it doesn't collapse you). Mana: what the fight spent net of collected flux and the
// rebate, at most what the player had. Mood: the outcome. Renown, Crowns and alignment: what the fight moved.
function settle(state,player){
 const s=COMBAT_TUNING.settle,a=state.actors[0],st=state.settlement?.[0],r=state.result;
 if(!r||!st)throw Error('Settle a finished fight');
 const outcome=r.winner===0?'win':r.winner===1?'lose':'draw';
 const lostShare=Math.max(0,(a.startHP??a.maxHP)-a.hp)/a.maxHP;
 const health=-Math.min(Math.round(lostShare*s.healthStake*(1-state.rebates.health)),Math.max(0,(player.health??0)-1));
 const mana=-Math.min(Math.max(0,Math.round(st.mana.netLoss)),player.mana??0);
 const gained=k=>-Math.round(st[k].netLoss);
 return {outcome,reason:r.reason,deltas:{health,mana,mood:s.mood[outcome],renown:gained('renown'),gold:gained('crowns'),alignment:gained('alignment')},followUps:r.followUps??[]};
}
const clamp=(x,lo,hi)=>Math.min(hi,Math.max(lo,x));

// ---- combat/web/core.mjs
// The combat rules and AI search for the browser: the Rust core (rust/core) compiled to WebAssembly (rust/wasm → core.wasm).
// This file only moves data across the boundary and keeps the engine's JS API, so app.mjs and its workers call the same names.
// A state stays a plain JS object (setup.mjs makes it; workers receive copies). Rule calls load it into the core when it is not
// the one already loaded; applyChoice and concede write the core's next state back into the same object.

const SYNC=Symbol('core-sync');
const imports={env:{now:()=>performance.now()}};
let coreModule=null,W,loaded=null,serial=0;
// A trap (a panic in the core) poisons the instance; start a fresh one and report the core's message.
function instantiate(){W=new WebAssembly.Instance(coreModule,imports).exports;W.init();loaded=null;}

const encoder=new TextEncoder(),decoder=new TextDecoder();
const read=()=>decoder.decode(new Uint8Array(W.memory.buffer,W.out_ptr(),W.out_len()));
// call(name, ...args): string arguments become (ptr, len) pairs in core memory, freed after the call.
function call(name,...args){
  const instance=W,owned=[],flat=[];
  for(const a of args){if(typeof a!=='string'){flat.push(a);continue;}const b=encoder.encode(a),p=W.alloc(b.length);new Uint8Array(W.memory.buffer,p,b.length).set(b);owned.push([p,b.length]);flat.push(p,b.length);}
  try{return W[name](...flat);}
  catch(e){if(!(e instanceof WebAssembly.RuntimeError))throw e;const message=read();instantiate();throw Error(message||e.message);}
  finally{if(W===instance)for(const [p,n] of owned)W.dealloc(p,n);}
}
function use(s){if(loaded!==s||s[SYNC]!==serial){call('load',JSON.stringify(s));loaded=s;s[SYNC]=++serial;}}
// The core's state after a change, written into the caller's object.
function writeBack(s){call('dump');const next=JSON.parse(read());for(const k of Object.keys(s))if(!(k in next))delete s[k];Object.assign(s,next);loaded=s;s[SYNC]=++serial;}

let RULES_VERSION=null;
const POLICY_VERSION='alpha-beta-2';
// Starts the core from a compiled WebAssembly.Module: the loader at the end of this file (the bench, Node), or the main game's
// bundle (build/combat.bundle.js, from combat/tools/bundle.mjs), which cuts that loader and passes the module it compiled.
function initCore(module){coreModule=module;instantiate();call('rules_version');RULES_VERSION=read();}
const coreReady=()=>!!coreModule;

function label(id){if(typeof id!=='string')return id;call('label',id);return read();}
// Event text, from the structured events the core returns.
function formatEvent(e){
  const who=side=>side===0?'You':'Opponent';
  switch(e.type){
    case 'constructEnded':return `${label(e.id)} ended.`;
    case 'froze':return `${who(e.side)} froze on 1 HP; thaw after next exchange.`;
    case 'witnessed':return `Observers witnessed forbidden ${label(e.id)}.`;
    case 'compelsCancel':return 'Opposing Compels cancel each other.';
    case 'tormentCharged':return `Torment charged ${e.value.toFixed(2)} HP for the action.`;
    case 'hoarfrostCancel':return 'Hoarfrost and opposing fire cancel.';
    case 'dealt':return `${label(e.id)} dealt ${Math.round(e.amount*100)/100} HP to ${e.target===0?'you':'opponent'}.`;
    case 'reclaimed':return `${who(e.side)} reclaimed ${e.amount.toFixed(2)} Mana.`;
    case 'hit':case 'moved':return null;   // structured only: the fight text (resolvedLines) tells these
  }
  throw Error('Unknown event '+e.type);
}

function cloneState(s){return structuredClone(s);}
function actorToMove(s){use(s);const side=call('actor');return side<0?null:side;}
function legalActions(s,side){use(s);call('legal',side??-1);return JSON.parse(read());}
